CREATE UNIQUE INDEX swarms_live_name ON swarms(project_id, name) WHERE state <> 'deleted';
CREATE UNIQUE INDEX managed_pools_live_name ON managed_pools(name) WHERE state <> 'deleted';
CREATE UNIQUE INDEX managed_actors_live_name ON managed_actors(swarm_id, name) WHERE phase <> 'deleted';
CREATE UNIQUE INDEX managed_actors_live_ctid ON managed_actors(cluster_identity, ctid) WHERE phase <> 'deleted';
CREATE TRIGGER managed_swarm_delete_guard BEFORE DELETE ON swarms WHEN EXISTS (SELECT 1 FROM managed_actors WHERE swarm_id = OLD.id AND phase <> 'deleted') BEGIN SELECT RAISE(ABORT, 'swarm has managed actors'); END;
CREATE TRIGGER swarm_steps_report_fence BEFORE UPDATE ON swarm_steps WHEN NEW.report IS NOT OLD.report AND (OLD.report IS NOT NULL OR OLD.state = 'completed') BEGIN SELECT RAISE(ABORT, 'step report is written once with the outcome'); END;
CREATE TRIGGER swarm_steps_pass_fence BEFORE UPDATE ON swarm_steps WHEN NEW.goal IS NOT OLD.goal OR NEW.source_commit IS NOT OLD.source_commit BEGIN SELECT RAISE(ABORT, 'pass goal and commit are written once with the first step of the pass'); END;
CREATE TRIGGER pipeline_sources_immutable BEFORE UPDATE ON pipeline_sources BEGIN SELECT RAISE(ABORT, 'pipeline source is immutable'); END;
CREATE TRIGGER pipeline_sources_no_replace BEFORE INSERT ON pipeline_sources WHEN EXISTS (SELECT 1 FROM pipeline_sources WHERE swarm_id=NEW.swarm_id) BEGIN SELECT RAISE(ABORT, 'pipeline source is immutable'); END;
CREATE TRIGGER pipeline_sources_no_delete BEFORE DELETE ON pipeline_sources WHEN EXISTS (SELECT 1 FROM swarms WHERE id=OLD.swarm_id) BEGIN SELECT RAISE(ABORT, 'pipeline source is immutable'); END;
CREATE TRIGGER swarm_graph_immutable BEFORE UPDATE ON swarms WHEN OLD.graph IS NOT NULL AND (NEW.graph IS NOT OLD.graph OR NEW.definition_name IS NOT OLD.definition_name OR NEW.definition_version IS NOT OLD.definition_version OR NEW.definition_revision IS NOT OLD.definition_revision) BEGIN SELECT RAISE(ABORT, 'swarm graph is immutable'); END;
CREATE TRIGGER swarms_no_replace BEFORE INSERT ON swarms WHEN EXISTS (SELECT 1 FROM swarms WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT, 'swarm already exists'); END;
CREATE TRIGGER swarm_steps_attested BEFORE UPDATE ON swarm_steps WHEN NEW.state IN ('delivering', 'inflight') AND EXISTS (SELECT 1 FROM pipeline_sources p WHERE p.swarm_id = NEW.swarm_id) AND COALESCE(NEW.source_commit, (SELECT s.source_commit FROM swarm_steps s WHERE s.swarm_id = NEW.swarm_id AND s.sequence <= NEW.sequence AND s.source_commit IS NOT NULL ORDER BY s.sequence DESC LIMIT 1)) IS NOT NEW.attested_commit BEGIN SELECT RAISE(ABORT, 'actor step requires a workspace attestation of its pass source'); END;
CREATE TRIGGER swarm_steps_attested_insert BEFORE INSERT ON swarm_steps WHEN NEW.state IN ('delivering', 'inflight') AND EXISTS (SELECT 1 FROM pipeline_sources p WHERE p.swarm_id = NEW.swarm_id) AND COALESCE(NEW.source_commit, (SELECT s.source_commit FROM swarm_steps s WHERE s.swarm_id = NEW.swarm_id AND s.sequence <= NEW.sequence AND s.source_commit IS NOT NULL ORDER BY s.sequence DESC LIMIT 1)) IS NOT NEW.attested_commit BEGIN SELECT RAISE(ABORT, 'actor step requires a workspace attestation of its pass source'); END;
CREATE UNIQUE INDEX swarm_requests_open_node ON swarm_requests(swarm_id) WHERE origin = 'node' AND state = 'open';
CREATE UNIQUE INDEX swarm_requests_step ON swarm_requests(swarm_id, sequence) WHERE origin = 'node';
CREATE TRIGGER swarm_requests_fence BEFORE UPDATE ON swarm_requests WHEN (OLD.state <> 'open' AND (NEW.state IS NOT OLD.state OR NEW.answered_at IS NOT OLD.answered_at OR NEW.answered_by IS NOT OLD.answered_by OR NEW.outcome IS NOT OLD.outcome OR NEW.response IS NOT OLD.response OR (NEW.delivery IS NOT OLD.delivery AND ((OLD.delivery IS NOT 'pending' AND OLD.delivery IS NOT 'failed' AND OLD.delivery IS NOT 'unconfirmed') OR NEW.delivery IS 'pending' OR (OLD.delivery IS 'unconfirmed' AND NEW.delivery IS 'failed'))))) OR NEW.id IS NOT OLD.id OR NEW.swarm_id IS NOT OLD.swarm_id OR NEW.sequence IS NOT OLD.sequence OR NEW.origin IS NOT OLD.origin OR NEW.actor_uid IS NOT OLD.actor_uid OR NEW.actor_incarnation IS NOT OLD.actor_incarnation OR NEW.kind IS NOT OLD.kind OR NEW.question IS NOT OLD.question OR NEW.context IS NOT OLD.context OR NEW.options IS NOT OLD.options OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT, 'swarm request is immutable'); END;
CREATE TRIGGER swarm_requests_no_delete BEFORE DELETE ON swarm_requests WHEN EXISTS (SELECT 1 FROM swarms WHERE id=OLD.swarm_id) BEGIN SELECT RAISE(ABORT, 'swarm request is permanent'); END;
CREATE TRIGGER swarm_requests_no_replace BEFORE INSERT ON swarm_requests WHEN EXISTS (SELECT 1 FROM swarm_requests WHERE id=NEW.id OR (NEW.origin='node' AND origin='node' AND swarm_id=NEW.swarm_id AND (sequence IS NEW.sequence OR (state='open' AND NEW.state='open')))) BEGIN SELECT RAISE(ABORT, 'swarm request is permanent'); END;
CREATE TRIGGER swarm_requests_cancel_guard BEFORE UPDATE OF state ON swarm_requests WHEN NEW.state = 'cancelled' AND OLD.origin = 'node' AND EXISTS (SELECT 1 FROM swarms WHERE id=OLD.swarm_id AND execution IN ('running', 'waiting')) BEGIN SELECT RAISE(ABORT, 'node request is closed by stopping the graph'); END;
CREATE TRIGGER swarms_gate_stop AFTER UPDATE OF execution ON swarms WHEN OLD.execution IN ('running', 'waiting') AND NEW.execution NOT IN ('running', 'waiting') BEGIN UPDATE swarm_requests SET state='cancelled' WHERE swarm_id=NEW.id AND origin='node' AND state='open'; END;
CREATE TRIGGER swarms_gate_resume BEFORE UPDATE OF execution ON swarms WHEN NEW.execution IN ('running', 'waiting') AND OLD.execution NOT IN ('running', 'waiting') AND EXISTS (SELECT 1 FROM swarm_steps s WHERE s.swarm_id=OLD.id AND s.state='waiting' AND NOT EXISTS (SELECT 1 FROM swarm_requests q WHERE q.swarm_id=s.swarm_id AND q.sequence=s.sequence AND q.origin='node' AND q.state='open')) BEGIN SELECT RAISE(ABORT, 'graph waits on a cancelled gate'); END;
PRAGMA user_version=26;
COMMIT;
